-- Migration: Seed D&D 5e Feats from Xanathar (XGE) and Tasha (TCE)
-- Idempotent upsert by (system, name)

insert into public.feats (system, name, category, prerequisites, description, ability_increase, source, is_homebrew)
values
-- =========================================================================
-- GUIA DO XANATHAR SOBRE TODAS AS COISAS (XGE)
-- =========================================================================
('dnd5e', 'Agilidade Élfica (Elven Accuracy)', 'Racial', 'Elfo ou Meio-Elfo', 'A precisão dos elfos é lendária, especialmente para arqueiros e conjuradores. Você tem uma mira sobrenatural com ataques que usam precisão ao invés de força bruta. Sempre que você tiver vantagem em uma jogada de ataque que use Destreza, Inteligência, Sabedoria ou Carisma, você pode rolar novamente um dos dados uma vez (vantagem tripla).', '+1 de Destreza, Inteligência, Sabedoria ou Carisma', 'XGE', false),

('dnd5e', 'Fúria dos Orcs (Orcish Fury)', 'Racial', 'Meio-Orc', 'A fúria de seus ancestrais orcs queima intensamente dentro de você. Uma vez por descanso curto ou longo, quando você acertar um ataque com uma arma simples ou marcial, você pode rolar um dos dados de dano da arma adicionalmente e somá-lo ao dano do ataque. Além disso, imediatamente após usar seu traço Resistência Implacável para não cair a 0 PV, você pode usar sua reação para fazer um ataque com arma.', '+1 de Força ou Constituição', 'XGE', false),

('dnd5e', 'Robustez dos Anões (Dwarven Fortitude)', 'Racial', 'Anão', 'O sangue resistente dos anões corre forte em suas veias, permitindo que você recupere vitalidade no calor da batalha. Sempre que você realizar a ação Esquivar (Dodge) em combate, você pode gastar um dos seus Dados de Vida disponíveis para recuperar pontos de vida iguais à rolagem do dado + seu modificador de Constituição (mínimo de 1 PV).', '+1 de Constituição', 'XGE', false),

('dnd5e', 'Asas de Draconato (Dragon Wings)', 'Racial', 'Draconato', 'Você desenvolve um par de asas draconianas resistentes nas suas costas. Você ganha um deslocamento de voo de 6 metros (20 pés), desde que não esteja vestindo armadura pesada nem esteja sobrecarregado.', '', 'XGE', false),

('dnd5e', 'Medo Dracônico (Dragon Fear)', 'Racial', 'Draconato', 'Quando você liberar sua herança draconiana, sua presença se torna aterrorizante. Em vez de liberar sua Arma de Sopro, você pode rugir e forçar cada criatura à sua escolha a até 9 metros de você que possa ver ou ouvir você a fazer uma salvaguarda de Sabedoria (CD = 8 + bônus de proficiência + mod de Carisma). Se falhar, a criatura fica amedrontada por 1 minuto. Ela pode repetir o teste ao sofrer dano.', '+1 de Força, Constituição ou Carisma', 'XGE', false),

('dnd5e', 'Pele de Dragão (Dragon Hide)', 'Racial', 'Draconato', 'Você manifesta traços físicos de seus ancestrais dragões. Suas escamas endurecem, concedendo CA igual a 13 + seu modificador de Destreza quando você não estiver usando armadura. Além disso, você desenvolve garras retráteis que causam 1d4 + mod de Força de dano cortante em ataques desarmados.', '+1 de Força, Constituição ou Carisma', 'XGE', false),

('dnd5e', 'Chamas de Phlegethos (Flames of Phlegethos)', 'Racial', 'Tiefling', 'Você aprende a controlar o fogo infernal que corre no seu sangue. Quando você rolar dano de fogo para uma magia que você conjurar, você pode rolar novamente qualquer resultado 1 nos dados de dano de fogo (devendo usar o novo resultado). Além disso, sempre que conjurar uma magia que cause dano de fogo, chamas mágicas envolvem seu corpo até o fim do seu próximo turno; qualquer criatura que atingir você com um ataque corpo-a-corpo a até 1,5m sofre 1d4 de dano de fogo.', '+1 de Inteligência ou Carisma', 'XGE', false),

('dnd5e', 'Constituição Infernal (Infernal Constitution)', 'Racial', 'Tiefling', 'O sangue diabólico fortalece seu corpo contra venenos e o frio das profundezas dos Nove Infernos. Você ganha resistência a dano de Frio e a dano de Veneno. Além disso, você tem vantagem em testes de salvaguarda contra ser envenenado.', '+1 de Constituição', 'XGE', false),

('dnd5e', 'Segunda Chance (Second Chance)', 'Racial', 'Halfling', 'A sorte dos halflings favorece você quando o perigo se aproxima. Quando uma criatura que você possa ver atingir você com uma jogada de ataque, você pode usar sua reação para forçar essa criatura a rolar novamente o ataque. Ela deve usar o novo resultado. Você recupera o uso deste talento após terminar um descanso curto ou longo.', '+1 de Destreza, Constituição ou Carisma', 'XGE', false),

('dnd5e', 'Sortudo Abundante (Bountiful Luck)', 'Racial', 'Halfling', 'Sua sorte natural é tão poderosa que transborda e protege seus companheiros de viagem. Quando um aliado que você possa ver a até 9 metros de você rolar um 1 natural em uma jogada de ataque, teste de habilidade ou salvaguarda, você pode usar sua reação para permitir que ele role o dado novamente. Você não pode usar seu traço Sortudo no seu próprio próximo turno se fizer isso.', '', 'XGE', false),

('dnd5e', 'Pele Esvaecente (Fade Away)', 'Racial', 'Gnomo', 'Você aprendeu a truques mágicos dos gnomos para desaparecer quando atacado. Imediatamente após você sofrer dano, você pode usar sua reação para ficar magicamente invisível até o final do seu próximo turno, ou até você atacar, causar dano ou conjurar uma magia. Você recupera este uso após terminar um descanso curto ou longo.', '+1 de Destreza ou Inteligência', 'XGE', false),

('dnd5e', 'Especialista em Agachamento (Squat Nimbleness)', 'Racial', 'Anão, Gnomo ou Halfling', 'Você é notavelmente ágil e veloz para seu tamanho diminuto. Seu deslocamento de caminhada aumenta em 1,5 metro (5 pés). Você ganha proficiência na perícia Atletismo ou Acrobacia (à sua escolha). Além disso, você tem vantagem em qualquer teste de Força (Atletismo) ou Destreza (Acrobacia) feito para escapar de ser agarrado.', '+1 de Força ou Destreza', 'XGE', false),

('dnd5e', 'Prodígio (Prodigy)', 'Geral', 'Humano, Meio-Elfo ou Meio-Orc', 'Você tem um talento nato e facilidade incomum para aprender qualquer perícia ou ofício. Você ganha proficiência em uma perícia à sua escolha, proficiência em uma ferramenta à sua escolha e fluência em um idioma adicional à sua escolha. Além disso, escolha uma perícia na qual você já seja proficiente: você ganha Especialização nela (seu bônus de proficiência é dobrado para qualquer teste que use essa perícia).', '', 'XGE', false),

('dnd5e', 'Teletransporte Feérico (Fey Teleportation)', 'Racial', 'Alto Elfo', 'Sua conexão ancestral com Faéria permite que você dobre o espaço ao seu redor. Você aprende o idioma Silvestre. Além disso, você aprende a magia Passo Nebuloso (Misty Step) e pode conjurá-la uma vez por descanso curto ou longo sem gastar um espaço de magia. Inteligência é sua habilidade de conjuração para ela.', '+1 de Inteligência ou Carisma', 'XGE', false),

('dnd5e', 'Magia dos Elfos da Floresta (Wood Elf Magic)', 'Racial', 'Elfo da Floresta', 'Você aprendeu a magia primordial das florestas ancestrais. Você aprende um truque de druida à sua escolha. Além disso, você aprende as magias Passos sem Pegadas (Pass Without Trace) e Criar ou Destruir Água (Create or Destroy Water), podendo conjurar cada uma delas uma vez por descanso longo sem gastar espaço de magia. Sabedoria é sua habilidade de conjuração.', '', 'XGE', false),

('dnd5e', 'Alta Magia Drow (High Drow Magic)', 'Racial', 'Elfo Drow', 'Você manifesta os dons arcanos superiores da nobreza dos elfos negros. Você aprende a magia Detectar Magia e pode conjurá-la à vontade, sem gastar espaços de magia. Você também aprende Levitação e Dissipar Magia, podendo conjurar cada uma uma vez por descanso longo sem gastar espaço de magia. Carisma é sua habilidade de conjuração.', '', 'XGE', false),

-- =========================================================================
-- CALDEIRÃO DE TASHA PARA TODAS AS COISAS (TCE)
-- =========================================================================
('dnd5e', 'Adepto Metamágico (Metamagic Adept)', 'Magia', 'Capacidade de conjurar magias', 'Você aprendeu como moldar e distorcer a tessitura da magia com técnicas de metamagia. Você aprende duas opções de Metamagia à sua escolha da lista da classe Feiticeiro. Você ganha 2 Pontos de Feitiçaria para gastar nessas opções (esses pontos são recuperados ao terminar um descanso longo). Se você já tiver pontos de feitiçaria, esses pontos são adicionados ao seu total.', '', 'TCE', false),

('dnd5e', 'Especialista em Perícias (Skill Expert)', 'Geral', '', 'Você treinou intensamente até alcançar a maestria técnica em uma área de especialidade. Você ganha proficiência em uma perícia à sua escolha. Além disso, escolha uma perícia na qual você já seja proficiente: você ganha Especialização nela (seu bônus de proficiência é dobrado para qualquer teste de habilidade feito com essa perícia).', '+1 em qualquer valor de Atributo', 'TCE', false),

('dnd5e', 'Tocado por Feéricos (Fey Touched)', 'Magia', '', 'Sua exposição à magia de Faéria alterou você misteriosamente. Você aprende a magia Passo Nebuloso (Misty Step) e uma magia de 1º círculo à sua escolha das escolas de Adivinhação ou Encantamento. Você pode conjurar cada uma dessas magias uma vez sem gastar espaços de magia por descanso longo. Você também pode conjurá-las normalmente usando seus próprios espaços de magia.', '+1 de Inteligência, Sabedoria ou Carisma', 'TCE', false),

('dnd5e', 'Tocado pelas Sombras (Shadow Touched)', 'Magia', '', 'Sua exposição às energias do Pendor das Sombras (Shadowfell) concedeu dons sombrios a você. Você aprende a magia Invisibilidade e uma magia de 1º círculo à sua escolha das escolas de Ilusão ou Necromancia. Você pode conjurar cada uma dessas magias uma vez sem gastar espaços de magia por descanso longo. Você também pode conjurá-las normalmente usando seus próprios espaços de magia.', '+1 de Inteligência, Sabedoria ou Carisma', 'TCE', false),

('dnd5e', 'Invocador Sobrenatural (Eldritch Adept)', 'Magia', 'Capacidade de conjurar magias ou classe Bruxo', 'Você desbloqueou segredos e fragmentos de conhecimento proibido de patronos transcendentais. Você aprende uma Invocação Mística (Eldritch Invocation) à sua escolha da classe Bruxo. Se a invocação tiver qualquer pré-requisito, você só pode escolhê-la se for um Bruxo que atenda a esse pré-requisito. Cada vez que você subir de nível, você pode trocar essa invocação por outra.', '', 'TCE', false),

('dnd5e', 'Iniciado em Artífice (Artificer Initiate)', 'Magia', '', 'Você compreendeu a união entre engenhocas mecânicas e fórmulas mágicas. Você aprende um truque da lista do Artífice e uma magia de 1º círculo do Artífice (podendo conjurá-la 1x por descanso longo sem espaço de magia ou usando seus próprios espaços). Você ganha proficiência com um tipo de ferramentas de artesão e pode usá-las como foco de conjuração.', '', 'TCE', false),

('dnd5e', 'Iniciado em Luta (Fighting Initiate)', 'Combate', 'Proficiência com arma marcial', 'Seu treinamento militar marcial concedeu uma técnica especializada de combate. Você aprende uma opção de Estilo de Luta (Fighting Style) à sua escolha da classe Guerreiro. Sempre que você subir de nível e receber um Aumento no Valor de Atributo, você pode trocar esse estilo por outro estilo de luta do Guerreiro.', '', 'TCE', false),

('dnd5e', 'Mestre Cozinheiro (Chef)', 'Geral', '', 'O tempo gasto na cozinha refinou suas habilidades culinárias para fortalecer seus aliados. Você ganha proficiência com ferramentas de cozinheiro. Ao final de um descanso curto, você pode preparar comida especial: qualquer aliado que gaste um ou mais Dados de Vida recupera 1d8 de PV adicionais. Além disso, ao final de um descanso longo, você pode criar uma quantidade de guloseimas especiais igual ao seu bônus de proficiência: consumir uma como ação bônus concede pontos de vida temporários iguais ao seu bônus de proficiência.', '+1 de Constituição ou Sabedoria', 'TCE', false),

('dnd5e', 'Perfurador (Piercer)', 'Combate', '', 'Você atinge pontos vitais com precisão cirúrgica em ataques perfurantes. Uma vez por turno, ao atingir uma criatura com um ataque que cause dano perfurante, você pode rolar novamente um dos dados de dano do ataque e deve usar o novo resultado. Além disso, quando você acertar um acerto crítico que cause dano perfurante a uma criatura, você pode rolar um dado de dano adicional ao determinar o dano extra do acerto crítico.', '+1 de Força ou Destreza', 'TCE', false),

('dnd5e', 'Triturador (Crusher)', 'Combate', '', 'Você domina o impacto contundente de suas armas para desequilibrar os inimigos. Uma vez por turno, ao atingir uma criatura com um ataque que cause dano de concussão, você pode empurrá-la 1,5 metro para um espaço desocupado, desde que a criatura não seja mais do que um tamanho maior que você. Além disso, quando você acerta um acerto crítico com dano de concussão, jogadas de ataque contra essa criatura têm vantagem até o início do seu próximo turno.', '+1 de Força ou Constituição', 'TCE', false),

('dnd5e', 'Cortador (Slasher)', 'Combate', '', 'Você desfere golpes cortantes profundos que mutilam a mobilidade dos alvos. Uma vez por turno, quando você atingir uma criatura com um ataque que cause dano cortante, você pode reduzir o deslocamento da criatura em 3 metros (10 pés) até o início do seu próximo turno. Além disso, quando você acerta um acerto crítico com dano cortante em uma criatura, ela sofre desvantagem em todas as jogadas de ataque que fizer até o início do seu próximo turno.', '+1 de Força ou Destreza', 'TCE', false),

('dnd5e', 'Telepata (Telepathic)', 'Geral', '', 'Você desperta o poder mental para conectar pensamentos e perscrutar mentes. Você pode se comunicar telepaticamente com qualquer criatura que possa ver a até 18 metros de você. A criatura compreende suas palavras se compartilhar um idioma com você. Além disso, você pode conjurar a magia Detectar Pensamentos (Detect Thoughts) uma vez sem gastar espaços de magia por descanso longo, sem necessitar de componentes verbais, somáticos ou materiais.', '+1 de Inteligência, Sabedoria ou Carisma', 'TCE', false),

('dnd5e', 'Telecinético (Telekinetic)', 'Geral', '', 'Você manipula objetos e pessoas com o poder bruto da mente. Você aprende o truque Mãos Mágicas (Mage Hand), podendo conjurá-lo sem componentes verbais ou somáticos, tornando a mão invisível e com alcance aumentado em 9 metros (30 pés). Além disso, com uma ação bônus, você pode tentar empurrar telepaticamente uma criatura visível a até 9 metros de você por 1,5m em sua direção ou para longe (salvaguarda de Força contra CD 8 + bônus de proficiência + atributo aumentado).', '+1 de Inteligência, Sabedoria ou Carisma', 'TCE', false),

('dnd5e', 'Atirador Tático (Gunner)', 'Combate', '', 'Você tem reflexos rápidos e maestria impecável no manuseio de armas de fogo. Você ganha proficiência com armas de fogo. Você ignora a propriedade de recarga (loading) de armas de fogo. Além disso, estar a até 1,5 metro de uma criatura hostil não impõe desvantagem em suas jogadas de ataque à distância.', '+1 de Destreza', 'TCE', false),

('dnd5e', 'Combatente Venenoso (Poisoner)', 'Geral', '', 'Você é um mestre no preparo e aplicação de toxinas mortais. Quando você faz uma jogada de dano, você ignora a resistência a dano de veneno do alvo. Você pode aplicar veneno a uma arma ou munição como uma ação bônus em vez de uma ação. Você ganha proficiência com kit de envenenador e pode criar doses de veneno potente durante um descanso longo com custo reduzido.', '+1 de Destreza ou Inteligência', 'TCE', false),

-- =========================================================================
-- LIVRO DO JOGADOR - TALENTOS COMPLEMENTARES (PHB)
-- =========================================================================
('dnd5e', 'Adepto Elemental (Elemental Adept)', 'Magia', 'Capacidade de conjurar pelo menos uma magia', 'Escolha um tipo de dano: Ácido, Frio, Fogo, Elétrico ou Trovão. Magias que você conjurar ignoram a resistência a dano do tipo escolhido. Além disso, quando você rolar dano para uma magia que você conjurar que cause dano desse tipo, você pode considerar qualquer resultado 1 no dado de dano como um 2.', '', 'PHB', false),

('dnd5e', 'Atirador de Elite (Spell Sniper)', 'Magia', 'Capacidade de conjurar pelo menos uma magia', 'Quando você conjura uma magia que exige que você faça uma jogada de ataque à distância, o alcance da magia é dobrado. Seus ataques de magia à distância ignoram meia cobertura e três quartos de cobertura. Além disso, você aprende um truque que requer uma jogada de ataque da lista de bardo, clérigo, druida, feiticeiro, bruxo ou mago.', '', 'PHB', false),

('dnd5e', 'Conjurador Ritual (Ritual Caster)', 'Magia', 'Inteligência ou Sabedoria 13+', 'Você adquire um livro de rituais com duas magias de 1º círculo que tenham o descritor ritual à sua escolha da lista de uma classe de conjurador. Você pode conjurar essas magias como rituais. Você pode transcrever outras magias rituais que encontrar pelo caminho se tiver nível de conjuração apropriado e tempo de estudo.', '', 'PHB', false),

('dnd5e', 'Líder Inspirador (Inspiring Leader)', 'Geral', 'Carisma 13+', 'Você pode passar 10 minutos inspirando seus companheiros com um discurso encorajador. Ao fazer isso, escolha até 6 criaturas aliadas (que podem incluir você mesmo) a até 9 metros de você. Cada criatura ganha pontos de vida temporários iguais ao seu nível + seu modificador de Carisma. Uma criatura não pode se beneficiar disso novamente até terminar um descanso curto ou longo.', '', 'PHB', false),

('dnd5e', 'Combatente Montado (Mounted Combatant)', 'Combate', '', 'Você é um cavaleiro formidável montado. Enquanto você estiver montado e não incapacitado, você tem vantagem em jogadas de ataque corpo-a-corpo contra qualquer criatura desmontada que seja menor que sua montaria. Você pode forçar um ataque direcionado à sua montaria a ter você como alvo. Se sua montaria sofrer um efeito que permita salvaguarda de Des para metade do dano, ela não sofre dano se passar e metade se falhar.', '', 'PHB', false),

('dnd5e', 'Mestre em Armaduras Pesadas (Heavy Armor Master)', 'Combate', 'Proficiência com armadura pesada', 'Enquanto você estiver vestindo armadura pesada, o dano cortante, perfurante e de concussão que você sofre de armas não-mágicas é reduzido em 3.', '+1 de Força', 'PHB', false),

('dnd5e', 'Atleta (Athlete)', 'Geral', '', 'Você treinou seu condicionamento físico ao extremo. Levantar-se da condição caído custa apenas 1,5 metro do seu deslocamento. Escalar não custa deslocamento adicional para você. Você pode fazer um salto em distância ou salto em altura correndo apenas 1,5m em vez de 3m.', '+1 de Força ou Destreza', 'PHB', false),

('dnd5e', 'Linguista (Linguist)', 'Geral', '', 'Você aprende três idiomas adicionais à sua escolha. Além disso, você pode criar cifras escritas e códigos secretos com maestria. Uma criatura que tente decifrar seu código deve ter sucesso em um teste de Inteligência (Investigação) contra uma CD igual a 8 + seu bônus de proficiência + seu mod de Inteligência.', '+1 de Inteligência', 'PHB', false)

on conflict do nothing;
